#define WARMUP false

void print_stats(std::string category, std::vector<float> percentiles,
                 std::vector<float> results) {
  diskann::cout << std::setw(20) << category << ": " << std::flush;
  for (uint32_t s = 0; s < percentiles.size(); s++) {
    diskann::cout << std::setw(8) << percentiles[s] << "%";
  }
  diskann::cout << std::endl;
  diskann::cout << std::setw(22) << " " << std::flush;
  for (uint32_t s = 0; s < percentiles.size(); s++) {
    diskann::cout << std::setw(9) << results[s];
  }
  diskann::cout << std::endl;
}

template<typename T>
int search_disk_index(diskann::Metric&   metric,
                      const std::string& index_path_prefix,
                      const std::string& mem_index_path,
                      const std::string& query_file, std::string& gt_file,
                      const std::string& disk_file_path,
                      const unsigned num_threads, const float search_range,
                      const unsigned               beamwidth,
                      const unsigned               num_nodes_to_cache,
                      const std::vector<unsigned>& Lvec,
                      const _u32 mem_L,
                      const unsigned kicked_size,
                      const unsigned custom_round_num,
                      const bool iter_knn_to_range_search,
                      const bool use_page_search,
                      const float use_ratio = 1.0f) {
  std::string pq_prefix = index_path_prefix + "_pq";
  std::string disk_index_file = index_path_prefix + "_disk.index";
  std::string warmup_query_file = index_path_prefix + "_sample_data.bin";

  diskann::cout << "Search parameters: #threads: " << num_threads << ", ";
  if (beamwidth <= 0)
    diskann::cout << "beamwidth to be optimized for each L value" << std::endl;
  else
    diskann::cout << " beamwidth: " << beamwidth << std::endl;

  // load query bin
  T*                             query = nullptr;
  std::vector<std::vector<_u32>> groundtruth_ids;
  size_t query_num, query_dim, query_aligned_dim, gt_num;
  diskann::load_aligned_bin<T>(query_file, query, query_num, query_dim,
                               query_aligned_dim);

  bool calc_recall_flag = false;
  if (gt_file != std::string("null") && file_exists(gt_file)) {
    diskann::load_range_truthset(
        gt_file, groundtruth_ids,
        gt_num);  // use for range search type of truthset
    //    diskann::prune_truthset_for_range(gt_file, search_range,
    //    groundtruth_ids, gt_num); // use for traditional truthset
    if (gt_num != query_num) {
      diskann::cout
          << "Error. Mismatch in number of queries and ground truth data"
          << std::endl;
      return -1;
    }
    calc_recall_flag = true;
  }

  std::shared_ptr<AlignedFileReader> reader = nullptr;
#ifdef _WINDOWS
#ifndef USE_BING_INFRA
  reader.reset(new WindowsAlignedFileReader());
#else
  reader.reset(new diskann::BingAlignedFileReader());
#endif
#else
  reader.reset(new LinuxAlignedFileReader());
#endif

  std::unique_ptr<diskann::PQFlashIndex<T>> _pFlashIndex(
      new diskann::PQFlashIndex<T>(reader, use_page_search, metric));

  int res = _pFlashIndex->load(num_threads, index_path_prefix.c_str(), disk_file_path);

  if (res != 0) {
    return res;
  }

  size_t load_mem = getCurrentRSS();

  // load in-memory navigation graph
  if (mem_L) {
    _pFlashIndex->load_mem_index(metric, query_aligned_dim, mem_index_path, num_threads, mem_L);
  }

  // cache bfs levels
  std::vector<uint32_t> node_list;
  diskann::cout << "Caching " << num_nodes_to_cache
                << " BFS nodes around medoid(s)" << std::endl;
  _pFlashIndex->cache_bfs_levels(num_nodes_to_cache, node_list);
  //  _pFlashIndex->generate_cache_list_from_sample_queries(
  //      warmup_query_file, 15, 6, num_nodes_to_cache, num_threads, node_list);
  _pFlashIndex->load_cache_list(node_list);
  node_list.clear();
  node_list.shrink_to_fit();

  size_t cache_mem = getCurrentRSS();

  omp_set_num_threads(num_threads);

  uint64_t warmup_L = 20;
  uint64_t warmup_num = 0, warmup_dim = 0, warmup_aligned_dim = 0;
  T*       warmup = nullptr;

  if (WARMUP) {
    if (file_exists(warmup_query_file)) {
      diskann::load_aligned_bin<T>(warmup_query_file, warmup, warmup_num,
                                   warmup_dim, warmup_aligned_dim);
    } else {
      warmup_num = (std::min)((_u32) 150000, (_u32) 15000 * num_threads);
      warmup_dim = query_dim;
      warmup_aligned_dim = query_aligned_dim;
      diskann::alloc_aligned(((void**) &warmup),
                             warmup_num * warmup_aligned_dim * sizeof(T),
                             8 * sizeof(T));
      std::memset(warmup, 0, warmup_num * warmup_aligned_dim * sizeof(T));
      std::random_device              rd;
      std::mt19937                    gen(rd());
      std::uniform_int_distribution<> dis(-128, 127);
      for (uint32_t i = 0; i < warmup_num; i++) {
        for (uint32_t d = 0; d < warmup_dim; d++) {
          warmup[i * warmup_aligned_dim + d] = (T) dis(gen);
        }
      }
    }
    diskann::cout << "Warming up index... " << std::flush;
    std::vector<uint64_t> warmup_result_ids_64(warmup_num, 0);
    std::vector<float>    warmup_result_dists(warmup_num, 0);

#pragma omp parallel for schedule(dynamic, 1)
    for (_s64 i = 0; i < (int64_t) warmup_num; i++) {
      _pFlashIndex->cached_beam_search(warmup + (i * warmup_aligned_dim), 1,
                                       warmup_L,
                                       warmup_result_ids_64.data() + (i * 1),
                                       warmup_result_dists.data() + (i * 1), 4);
    }
    diskann::cout << "..done" << std::endl;
  }

  diskann::cout.setf(std::ios_base::fixed, std::ios_base::floatfield);
  diskann::cout.precision(2);

  std::string recall_string = "Recall@rng=" + std::to_string(search_range);
  diskann::cout << std::setw(6) << "L" << std::setw(10) << "MEM_L"
                << std::setw(12) << "Kicked Size"
                << std::setw(12) << "Beamwidth"
                << std::setw(16) << "QPS" << std::setw(16) << "Mean Latency"
                << std::setw(16) << "99.9 Latency" << std::setw(16)
                << "Mean IOs" << std::setw(16) << "CPU"
                << std::setw(20) << "B4 Load In-Mem"
                << std::setw(20) << "After Load Cache"
                << std::setw(15) << "Peak Mem(MB)";
  if (calc_recall_flag) {
    diskann::cout << std::setw(16) << recall_string << std::endl;
  } else
    diskann::cout << std::endl;
  diskann::cout
      << "==============================================================="
         "==========================================="
      << std::endl;

  std::vector<std::vector<std::vector<uint64_t>>> query_result_ids(Lvec.size());

  uint32_t optimized_beamwidth = 2;
  uint32_t max_list_size = 10000;

  for (uint32_t test_id = 0; test_id < Lvec.size(); test_id++) {
    _u64 L = Lvec[test_id];

    if (beamwidth <= 0) {
      optimized_beamwidth =
          optimize_beamwidth(_pFlashIndex, warmup, warmup_num,
                             warmup_aligned_dim, L, optimized_beamwidth);
    } else
      optimized_beamwidth = beamwidth;

    query_result_ids[test_id].clear();
    query_result_ids[test_id].resize(query_num);

    diskann::QueryStats* stats = new diskann::QueryStats[query_num];

    auto s = std::chrono::high_resolution_clock::now();
    // whether use iterative knn strategy to do range search
    // range_search_iter_knn() checks use_page_search_ 
    // to switch between knn methods
    if (iter_knn_to_range_search) {
      if (kicked_size) {
        // if (mem_L <= 0) {
        //   diskann::cerr << "MEM_L should be greater than 0" << std::endl;
        //   return -1;
        // }

        std::cout << "Iterative KNN page search using intermediate states" << std::endl;
#pragma omp parallel for schedule(dynamic, 1)
        for (_s64 i = 0; i < (int64_t) query_num; i++) {
          std::vector<float> distances;
          std::vector<unsigned> mem_tags;
          std::vector<float> mem_dis;
          _pFlashIndex->custom_range_search_iter_page_search(
              query + (i * query_aligned_dim), search_range, mem_L, mem_tags, mem_dis, L, max_list_size,
              query_result_ids[test_id][i], distances, optimized_beamwidth, use_ratio,
              kicked_size,
              stats + i);
        }
      } else {
        std::cout << "Iterative KNN search use_page_search: " << use_page_search << std::endl;
#pragma omp parallel for schedule(dynamic, 1)
        for (_s64 i = 0; i < (int64_t) query_num; i++) {
          std::vector<float> distances;
          _pFlashIndex->range_search_iter_knn(
              query + (i * query_aligned_dim), search_range, mem_L, L, max_list_size,
              query_result_ids[test_id][i], distances, optimized_beamwidth, use_ratio,
              stats + i);
        }
      }
    } else {
      if (mem_L <= 0) {
        diskann::cerr << "Custom range search needs in-memory navigation graph, set mem_L larger than 0" << std::endl;
        return -1;
      }
      if (!use_page_search) {
        diskann::cerr << "Custom range search needs use_page_search set to 1" << std::endl;
        return -1;
      }
      if (kicked_size <= 0) {
        diskann::cerr << "Kicked size should be non-zero" << std::endl;
        return -1;
      }
      std::cout << "Use custom range search" << std::endl;

#pragma omp parallel for schedule(dynamic, 1)
      for (_s64 i = 0; i < (int64_t) query_num; i++) {
        std::vector<float> distances;
        _pFlashIndex->custom_range_search(
            query + (i * query_aligned_dim), search_range, mem_L, L, max_list_size,
            query_result_ids[test_id][i], distances, optimized_beamwidth,
            use_ratio, kicked_size, custom_round_num, stats + i);
      }
    }
    auto                          e = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> diff = e - s;
    auto qps = (1.0 * query_num) / (1.0 * diff.count());

    auto mean_latency = diskann::get_mean_stats<float>(
        stats, query_num,
        [](const diskann::QueryStats& stats) { return stats.total_us.load(); });

    auto latency_999 = diskann::get_percentile_stats<float>(
        stats, query_num, 0.999,
        [](const diskann::QueryStats& stats) { return stats.total_us.load(); });
    auto mean_ios = diskann::get_mean_stats<unsigned>(
        stats, query_num,
        [](const diskann::QueryStats& stats) { return stats.n_ios.load(); });

    float mean_cpus = diskann::get_mean_stats<float>(
        stats, query_num,
        [](const diskann::QueryStats& stats) { return stats.cpu_us.load(); });
    float recall = 0;
    float ratio_of_sums = 0;
    if (calc_recall_flag) {
      recall = diskann::calculate_range_search_recall(
          query_num, groundtruth_ids, query_result_ids[test_id]);

      _u32 total_true_positive = 0;
      _u32 total_positive = 0;
      for (_u32 i = 0; i < query_num; i++) {
        total_true_positive += query_result_ids[test_id][i].size();
        total_positive += groundtruth_ids[i].size();
      }

      ratio_of_sums = (1.0 * total_true_positive) / (1.0 * total_positive) * 100;
    }

    diskann::cout << std::setw(6) << L << std::setw(10) << mem_L
                  << std::setw(12) << kicked_size
                  << std::setw(12) << optimized_beamwidth
                  << std::setw(16) << qps << std::setw(16) << mean_latency
                  << std::setw(16) << latency_999 << std::setw(16) << mean_ios
                  << std::setw(16) << mean_cpus
                  << std::setw(20) << load_mem
                  << std::setw(20) << cache_mem
                  << std::setw(15) << getProcessPeakRSS();
    if (calc_recall_flag) {
      diskann::cout << std::setw(16) << recall << "," << ratio_of_sums
                    << std::endl;
    } else
      diskann::cout << std::endl;
  }

  diskann::cout << "Done searching. " << std::endl;

  diskann::aligned_free(query);
  if (warmup != nullptr)
    diskann::aligned_free(warmup);
  return 0;
}

int main(int argc, char** argv) {
  std::string data_type, dist_fn, index_path_prefix, result_path_prefix,
      query_file, gt_file, disk_file_path, mem_index_path;
